import{_ as e,o as a,c as r,a6 as i}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"設計は「変更の置き場所」を決めること","description":"","frontmatter":{"title":"設計は「変更の置き場所」を決めること","study":{"source":"設計の手帖","kind":"本文","status":"既存原稿","summary":"きれいなクラス図よりも、次の変更をどこに書けばよいか分かること。設計の出発点をここに置きます。"}},"headers":[],"relativePath":"design/notebook/thinking.md","filePath":"design/notebook/thinking.md"}'),o={name:"design/notebook/thinking.md"};function n(d,t,s,l,h,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="設計は「変更の置き場所」を決めること" tabindex="-1">設計は「変更の置き場所」を決めること <a class="header-anchor" href="#設計は「変更の置き場所」を決めること" aria-label="Permalink to &quot;設計は「変更の置き場所」を決めること&quot;">​</a></h1><p>きれいなクラス図よりも、次の変更をどこに書けばよいか分かること。設計の出発点をここに置きます。</p><p>01 · 設計の土台 / 設計の目的と考え方 / Think in responsibilities / 入門 / 7分</p><p>タグ: 責務 / 凝集度 / 結合度 / KISS / YAGNI / DRY</p><h2 id="設計で決めるのは、責務・境界・依存関係" tabindex="-1">設計で決めるのは、責務・境界・依存関係 <a class="header-anchor" href="#設計で決めるのは、責務・境界・依存関係" aria-label="Permalink to &quot;設計で決めるのは、責務・境界・依存関係&quot;">​</a></h2><div><p>家計簿アプリに「CSV 出力」を追加するとします。金額の集計、CSV の書式、保存先の選択が一つの画面クラスに混ざると、書式の変更だけで画面や計算まで確認が必要になります。計算は <code>ExpenseSummary</code>、変換は <code>CsvExporter</code>、入出力は <code>FileStorage</code> に分けると、それぞれの変更理由が見えてきます。</p><p><strong>責務</strong>は「何を知り、何を決めるか」、<strong>境界</strong>は「どこまでを一まとまりとするか」、<strong>依存</strong>は「何の契約を知っている必要があるか」です。クラス数を増やすこと自体は目標ではありません。小さな処理なら、一つの関数と構造体で十分です。</p></div><h2 id="高凝集・低結合を具体的に考える" tabindex="-1">高凝集・低結合を具体的に考える <a class="header-anchor" href="#高凝集・低結合を具体的に考える" aria-label="Permalink to &quot;高凝集・低結合を具体的に考える&quot;">​</a></h2><div><div class="table-scroll"><table><thead><tr><th>考え方</th><th>よい兆候</th><th>見直す兆候</th></tr></thead><tbody><tr><td>高凝集</td><td>送料のルールが ShippingPolicy にまとまる</td><td>送料の式が画面・DB・帳票へ散らばる</td></tr><tr><td>低結合</td><td>集計処理が表示形式を知らない</td><td>集計のテストに UI と DB の起動が必要</td></tr><tr><td>情報隠蔽</td><td>利用者が内部の保存形式を知らずに使える</td><td>外部がフィールドを書き換え、整合性を保っている</td></tr></tbody></table></div><p>依存関係をゼロにはできません。変わりやすい詳細を閉じ込め、安定した契約に依存させます。クラスを細分化した結果、少しの変更で十数個のクラスを巡回するなら、その境界は再考する価値があります。</p></div><h2 id="まず覚える三つのブレーキ" tabindex="-1">まず覚える三つのブレーキ <a class="header-anchor" href="#まず覚える三つのブレーキ" aria-label="Permalink to &quot;まず覚える三つのブレーキ&quot;">​</a></h2><div><ul><li><strong>KISS：</strong>現在の要件を満たす、説明しやすい実装にする。短いコードと単純なコードは同じではありません。</li><li><strong>YAGNI：</strong>まだ必要でない拡張点を先回りして大量に作らない。具体的な変更要求が出てから抽象化しても遅くない場合が多くあります。</li><li><strong>DRY：</strong>同じ知識・ルールを重複させない。たまたま似た二つの式を、意味の違いを無視して共通化しない。</li></ul><aside class="article-note"><strong>判断の問い</strong><p>「この設計で、どの変更が簡単になるか。その代わりに、読む手間や運用の負担は何が増えるか」を一文で説明してみましょう。</p></aside></div><h2 id="学習の進め方" tabindex="-1">学習の進め方 <a class="header-anchor" href="#学習の進め方" aria-label="Permalink to &quot;学習の進め方&quot;">​</a></h2><div><p>まず第1〜4章で責務と依存を理解し、第5〜8章で小さな道具を覚えます。次に第9〜11章でアプリ全体を整理し、第12・13章で言語固有の設計へ進みます。最後に命名辞典を横に置いて、小さなアプリを改良してください。構文の基礎を知っている人を想定しています。</p><p>この手帖の注文・価格・画面の例は学習用です。コードは原則 C++20 / C# 12 で表せる抜粋で、各ブロックは独立しています。省略した周辺処理は注記し、外部サービスへ接続するコードは含めていません。</p></div><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><p>CSV の列の並びを変えるとき、集計ロジックまで変更する必要がありますか？</p><h2 id="この章の参考資料" tabindex="-1">この章の参考資料 <a class="header-anchor" href="#この章の参考資料" aria-label="Permalink to &quot;この章の参考資料&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/modern-web-apps-azure-architecture/common-web-application-architectures" target="_blank" rel="noreferrer">Common web application architectures</a> — Microsoft Learn。レイヤーと、Application Core へ向ける依存関係。</li><li><a href="https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines" target="_blank" rel="noreferrer">C++ Core Guidelines</a> — Bjarne Stroustrup / Herb Sutter ほか。インターフェース、所有権、クラス設計の指針。規格書そのものではありません。</li></ul><p><a href="/study/design/naming.html">クラス名辞典</a> / <a href="/study/design/pattern-index.html">パターン一覧</a> / <a href="/study/design/notebook-references.html">手帖の参考資料</a></p>',17)])])}const b=e(o,[["render",n]]);export{u as __pageData,b as default};
